SELECT ?z ?ts ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  OPTIONAL { ?z ref:hasTimeseriesId ?ts }
}

SELECT ?sensor ?label ?ts WHERE {
  ?sensor a brick:AirTemperatureSensor .
  OPTIONAL { ?sensor rdfs:label ?label }
  OPTIONAL { ?sensor ref:hasTimeseriesId ?ts }
}

SELECT ?label ?unit ?tsref WHERE {
  ?s a brick:AirTemperatureSensor .
  ?s rdfs:label ?label .
  OPTIONAL { ?s qudt:hasUnit ?unit }
  ?s brick:hasLocation ?loc ; brick:ref#hasExternalReference ?ts .
  ?ts brick:ref#hasTimeseriesId ?tsref .
  FILTER (STRSTARTS(?label, "Perimeter_mid_ZN_2") || STRSTARTS(?label, "Core_mid "))
}

